    21	const map = (
    22	  product: PdpSourceProduct | null | undefined,
    23	  price: { currentPrice?: number } | null = { currentPrice: 895 },
    24	) => selectPdpProductInfo(product, price, 'AUD', formatPrice);
    25	
    26	describe('selectPdpProductInfo — every field reaches the right prop', () => {
    27	  test.each`
    28	    prop             | source                      | expected
    29	    ${'name'}        | ${'name'}                   | ${'Natura Mini Dress'}
    30	    ${'description'} | ${'longDescription'}        | ${'<p>A long sleeve linen mini dress.</p>'}
    31	    ${'modelInfo'}   | ${'c_modelFit'}             | ${'Model is 178cm and wears a size 0'}
    32	    ${'styleCode'}   | ${'master.masterId'}        | ${'MASTER-STYLE-8637'}
    33	    ${'price'}       | ${'priceData.currentPrice'} | ${'AUD 895.00'}
    34	  `('$prop <- $source', ({ prop, expected }) => {
    35	    expect(map(FULL)?.[prop as keyof ReturnType<typeof map> & string]).toBe(expected);
    36	  });
    37	
    38	  test('styleCode is the master style number, not the variant id', () => {
    39	    // The regression this pins: after the first swatch click `product.id` becomes the variant
    40	    // SKU while the style code shown to shoppers must not change.
    41	    expect(map(FULL)?.styleCode).toBe('MASTER-STYLE-8637');
    42	    expect(map(FULL)?.styleCode).not.toBe(FULL.id);
    43	  });
    44	
