     1	/**
     2	 * `parseRichText` is the seam between Business-Manager-authored copy and the DOM, so its
     3	 * rejection behaviour is the thing worth pinning down. Every hostile-input case below is a
     4	 * row in one table, asserted against the *rendered* markup rather than the node tree — that
     5	 * is the form an attacker would have to reach, and it is what a reviewer can read at a glance.
     6	 *
     7	 * `renderToStaticMarkup` is deliberate: it proves the output as React actually serialises it,
     8	 * including React's own text escaping, rather than re-implementing that escaping in the test.
     9	 */
    10	import { describe, expect, test } from 'vitest';
    11	import React from 'react';
    12	import { renderToStaticMarkup } from 'react-dom/server';
    13	import { decodeEntities, isBlankRichText, parseRichText, richTextToPlainText } from './richText';
    14	
    15	const render = (input?: string | null) => renderToStaticMarkup(<>{parseRichText(input)}</>);
    16	
    17	describe('parseRichText — rejection matrix', () => {
    18	  // Each row: what an attacker or a bad CMS paste could put in the field, and what must
    19	  // survive. `mustNotContain` is checked against the serialised markup.
    20	  test.each`
    21	    name                           | input                                                  | mustNotContain    | mustContain
    22	    ${'script element'}            | ${'<p>hi</p><script>alert(1)</script>'}                | ${'<script'}      | ${'<p>hi</p>'}
    23	    ${'script body is not text'}   | ${'<script>stealCookies()</script>'}                   | ${'stealCookies'} | ${''}
    24	    ${'uppercase SCRIPT'}          | ${'<SCRIPT>alert(1)</SCRIPT>ok'}                       | ${'alert(1)'}     | ${'ok'}
    25	    ${'nested script'}             | ${'<script><script>alert(1)</script></script>safe'}    | ${'alert'}        | ${'safe'}
    26	    ${'inline event handler'}      | ${'<p onclick="evil()">text</p>'}                      | ${'onclick'}      | ${'<p>text</p>'}
    27	    ${'img onerror'}               | ${'<img src=x onerror=alert(1)>caption'}               | ${'onerror'}      | ${'caption'}
    28	    ${'javascript: href'}          | ${'<a href="javascript:alert(1)">link</a>'}            | ${'javascript:'}  | ${'link'}
    29	    ${'data: href'}                | ${'<a href="data:text/html,<script>x</script>">l</a>'} | ${'data:'}        | ${'l'}
    30	    ${'iframe'}                    | ${'<iframe src="https://evil.test"></iframe>after'}    | ${'<iframe'}      | ${'after'}
    31	    ${'svg onload'}                | ${'<svg onload=alert(1)></svg>tail'}                   | ${'onload'}       | ${'tail'}
    32	    ${'style block'}               | ${'<style>body{display:none}</style>copy'}             | ${'display:none'} | ${'copy'}
    33	    ${'form and input'}            | ${'<form><input value="x"></form>body'}                | ${'<input'}       | ${'body'}
    34	    ${'object embed'}              | ${'<object data="x"></object><embed src="y">z'}        | ${'<object'}      | ${'z'}
    35	    ${'class attribute stripped'}  | ${'<p class="leak">t</p>'}                             | ${'class'}        | ${'<p>t</p>'}
    36	    ${'style attribute stripped'}  | ${'<p style="position:fixed">t</p>'}                   | ${'style'}        | ${'<p>t</p>'}
    37	    ${'id attribute stripped'}     | ${'<li id="x">t</li>'}                                 | ${'id='}          | ${'<li>t</li>'}
    38	    ${'encoded script stays text'} | ${'&lt;script&gt;alert(1)&lt;/script&gt;'}             | ${'<script'}      | ${'&lt;script&gt;'}
    39	    ${'attr value containing gt'}  | ${'<a title="a > b">shown</a>'}                        | ${'title'}        | ${'shown'}
    40	    ${'unknown tag is unwrapped'}  | ${'<div><span>kept</span></div>'}                      | ${'<div'}         | ${'kept'}
    41	    ${'comment-ish input'}         | ${'<!-- <script>x</script> -->visible'}                | ${'<script'}      | ${'visible'}
    42	  `('$name', ({ input, mustNotContain, mustContain }) => {
    43	    const markup = render(input as string);
    44	    if (mustNotContain) expect(markup).not.toContain(mustNotContain as string);
    45	    if (mustContain) expect(markup).toContain(mustContain as string);
    46	  });
    47	
    48	  test('no rejection case ever emits an executable element', () => {
    49	    // Guards the table above against a silently-empty run (a suite that collects nothing
    50	    // passes vacuously). If a row is deleted this count drops and the test fails.
    51	    const hostile = [
    52	      '<script>a</script>',
    53	      '<iframe></iframe>',
    54	      '<img src=x onerror=y>',
    55	      '<svg onload=y></svg>',
    56	      '<object></object>',
    57	      '<embed>',
    58	      '<style>a{}</style>',
    59	      '<form><input></form>',
    60	    ];
    61	    expect(hostile).toHaveLength(8);
    62	    for (const input of hostile) {
    63	      const markup = render(input);
    64	      expect(markup).not.toMatch(/<(script|iframe|img|svg|object|embed|style|form|input)\b/i);
    65	      expect(markup).not.toMatch(/\son[a-z]+=/i);
    66	    }
    67	  });
    68	});
    69	
    70	describe('parseRichText — real SFCC copy', () => {
    71	  // The actual shape returned by the Shopper Products API for 8637DS241 (AU, 2026-08-23).
    72	  const REAL = [
    73	    'The Natura Mini Dress in Blue Birds from our Spring 2024 Collection, Natura. ',
    74	    'A long sleeve linen mini dress featuring a deep v-neckline with fitted bodice and full skirt. ',
    75	    '<br><ul><li> Linen mini dress</li><li> Long sleeves with fluted cuffs </li>',
    76	    '<li> Crinoline hem </li><li> Invisible zip at centre back</li></ul>',
    77	  ].join('');
    78	
    79	  test('preserves the tags Business Manager actually authors', () => {
    80	    const markup = render(REAL);
    81	    expect(markup).toContain('<br/>');
    82	    expect(markup).toContain('<ul>');
    83	    expect(markup).toContain('<li> Linen mini dress</li>');
    84	    expect(markup).toContain('Invisible zip at centre back');
    85	  });
    86	
    87	  test('emits no stray text node inside a list container', () => {
    88	    // `<ul>` may only hold `<li>`; whitespace between items must not become a text child.
    89	    expect(render('<ul>\n  <li>a</li>\n  <li>b</li>\n</ul>')).toBe('<ul><li>a</li><li>b</li></ul>');
    90	  });
    91	
    92	  test('keeps non-whitespace text that is not inside a list', () => {
    93	    expect(render('lead in<ul><li>a</li></ul>tail')).toBe('lead in<ul><li>a</li></ul>tail');
    94	  });
    95	});
    96	
    97	describe('parseRichText — malformed input', () => {
    98	  test.each([
    99	    ['unclosed tag', '<p>text', '<p>text</p>'],
   100	    ['stray close tag', 'text</p>', 'text'],
   101	    ['mismatched nesting', '<strong><em>x</strong></em>', '<strong><em>x</em></strong>'],
   102	    ['self-closed container', '<p/>after', 'after'],
   103	    ['bare angle bracket', 'a < b and c > d', 'a &lt; b and c &gt; d'],
   104	  ])('%s', (_name, input, expected) => {
   105	    expect(render(input)).toBe(expected);
   106	  });
   107	
   108	  test.each([undefined, null, ''])('renders nothing for %s', (input) => {
   109	    expect(parseRichText(input)).toEqual([]);
   110	    expect(render(input)).toBe('');
   111	  });
   112	});
   113	
   114	describe('decodeEntities', () => {
   115	  test.each([
   116	    ['&amp;', '&'],
   117	    ['&lt;&gt;', '<>'],
   118	    ['&quot;q&quot;', '"q"'],
   119	    ['&#39;', "'"],
   120	    ['&#x27;', "'"],
   121	    ['&nbsp;', ' '],
   122	    ['&rsquo;', '’'],
   123	    ['5&deg; &mdash; 6&deg;', '5° — 6°'],
   124	  ])('decodes %s', (input, expected) => {
   125	    expect(decodeEntities(input)).toBe(expected);
   126	  });
   127	
   128	  test.each(['&notarealentity;', '&#0;', '&#x110000;', '&', '&;'])('leaves %s untouched', (input) => {
   129	    expect(decodeEntities(input)).toBe(input);
   130	  });
   131	});
   132	
   133	describe('richTextToPlainText / isBlankRichText', () => {
   134	  test.each([
   135	    ['<p>Hello <strong>there</strong></p>', 'Hello there'],
   136	    ['<ul><li>a</li><li>b</li></ul>', 'ab'],
   137	    ['plain', 'plain'],
   138	    ['<p>a</p><script>dropped()</script>', 'a'],
   139	    ['&amp; entities decoded', '& entities decoded'],
   140	  ])('%s -> %s', (input, expected) => {
   141	    expect(richTextToPlainText(input)).toBe(expected);
   142	  });
   143	
   144	  test.each([undefined, null, '', '   ', '<p></p>', '<p>  </p>', '<br>', '<ul></ul>', '<script>x()</script>'])(
   145	    'treats %s as blank',
   146	    (input) => {
   147	      expect(isBlankRichText(input)).toBe(true);
   148	    },
   149	  );
   150	
   151	  test.each(['<p>a</p>', 'a', '<ul><li>a</li></ul>', '&nbsp;x'])('treats %s as non-blank', (input) => {
   152	    expect(isBlankRichText(input)).toBe(false);
   153	  });
   154	});

